import pandas as pd
import json
import math
from datetime import datetime

df = pd.read_csv('/app/benchmark/data.csv')
with open('/app/analysis_results.json', 'r') as f:
    R = json.load(f)

cities = R['cities']
overview = R['overview']
price_data = R['price_data']
host_data = R['host_data']
entire_home_data = R['entire_home_data']
demand_data = R['demand_data']
avail_data = R['avail_data']
dispersion = R['dispersion']

cities_with_prices = [c for c in cities if overview[c]['price_median'] is not None]
cities_no_prices = [c for c in cities if overview[c]['price_median'] is None]

# Sort cities by listing count for display
cities_by_size = sorted(cities, key=lambda c: overview[c]['total_listings'], reverse=True)

# Color palette
COLORS = {
    'Amsterdam': '#FF6B35',
    'Bangkok': '#F7C948',
    'Barcelona': '#E63946',
    'London': '#457B9D',
    'Paris': '#2A9D8F',
    'Rome': '#E76F51',
    'Sydney': '#264653',
}

CHART_COLORS = ['#457B9D', '#E63946', '#2A9D8F', '#FF6B35', '#F7C948', '#E76F51', '#264653']

def fmt_price(val):
    if val is None:
        return 'N/A'
    if val >= 1000:
        return f'{val:,.0f}'
    return f'{val:,.0f}'

def make_bar_svg(data_dict, title, width=700, bar_height=32, prefix='$', suffix='', max_val=None, note=None, color='#457B9D'):
    """Generate horizontal bar chart SVG."""
    items = list(data_dict.items())
    n = len(items)
    margin_left = 110
    margin_right = 80
    margin_top = 40
    margin_bottom = 30 if not note else 55
    chart_w = width - margin_left - margin_right
    chart_h = n * (bar_height + 8) + 10
    total_h = chart_h + margin_top + margin_bottom

    if max_val is None:
        max_val = max(v for _, v in items if v is not None and v > 0) * 1.15

    svg = f'<svg width="{width}" height="{total_h}" xmlns="http://www.w3.org/2000/svg" style="font-family:Inter,system-ui,sans-serif">\n'
    svg += f'<text x="{width/2}" y="22" text-anchor="middle" font-size="14" font-weight="600" fill="#1a1a2e">{title}</text>\n'

    for i, (label, val) in enumerate(items):
        y = margin_top + i * (bar_height + 8)
        svg += f'<text x="{margin_left - 10}" y="{y + bar_height/2 + 5}" text-anchor="end" font-size="12" fill="#333">{label}</text>\n'

        if val is not None and val > 0:
            bw = (val / max_val) * chart_w
            bw = max(bw, 2)
            svg += f'<rect x="{margin_left}" y="{y}" width="{bw}" height="{bar_height}" rx="4" fill="{color}" opacity="0.85"/>\n'
            label_text = f'{prefix}{val:,.0f}{suffix}' if isinstance(val, (int, float)) else str(val)
            svg += f'<text x="{margin_left + bw + 6}" y="{y + bar_height/2 + 5}" font-size="12" font-weight="500" fill="#333">{label_text}</text>\n'
        else:
            svg += f'<text x="{margin_left + 6}" y="{y + bar_height/2 + 5}" font-size="11" fill="#999">No data</text>\n'

    if note:
        svg += f'<text x="{width/2}" y="{total_h - 8}" text-anchor="middle" font-size="10" fill="#888" font-style="italic">{note}</text>\n'

    svg += '</svg>'
    return svg

def make_grouped_bar_svg(data, categories, groups, title, width=750, prefix='$'):
    """Grouped horizontal bar chart for room type pricing."""
    n_groups = len(groups)
    n_cats = len(categories)
    bar_h = 18
    group_gap = 15
    margin_left = 110
    margin_right = 100
    margin_top = 55
    margin_bottom = 40

    group_height = n_cats * (bar_h + 2) + group_gap
    chart_h = n_groups * group_height
    total_h = chart_h + margin_top + margin_bottom
    chart_w = width - margin_left - margin_right

    all_vals = []
    for g in groups:
        for c in categories:
            if g in data and c in data[g]:
                all_vals.append(data[g][c])
    max_val = max(all_vals) * 1.15 if all_vals else 100

    cat_colors = ['#457B9D', '#E63946', '#2A9D8F', '#F7C948']

    svg = f'<svg width="{width}" height="{total_h}" xmlns="http://www.w3.org/2000/svg" style="font-family:Inter,system-ui,sans-serif">\n'
    svg += f'<text x="{width/2}" y="22" text-anchor="middle" font-size="14" font-weight="600" fill="#1a1a2e">{title}</text>\n'

    # Legend
    lx = margin_left
    for i, c in enumerate(categories):
        svg += f'<rect x="{lx}" y="32" width="12" height="12" rx="2" fill="{cat_colors[i]}"/>\n'
        svg += f'<text x="{lx+16}" y="43" font-size="10" fill="#555">{c}</text>\n'
        lx += len(c) * 6 + 30

    for gi, g in enumerate(groups):
        gy = margin_top + gi * group_height
        svg += f'<text x="{margin_left - 10}" y="{gy + group_height/2 - 5}" text-anchor="end" font-size="12" fill="#333">{g}</text>\n'

        for ci, c in enumerate(categories):
            by = gy + ci * (bar_h + 2)
            val = data.get(g, {}).get(c, None)
            if val is not None and val > 0:
                bw = max((val / max_val) * chart_w, 2)
                svg += f'<rect x="{margin_left}" y="{by}" width="{bw}" height="{bar_h}" rx="3" fill="{cat_colors[ci]}" opacity="0.8"/>\n'
                svg += f'<text x="{margin_left + bw + 5}" y="{by + bar_h/2 + 4}" font-size="10" fill="#555">{prefix}{val:,.0f}</text>\n'

    svg += '</svg>'
    return svg

def make_stacked_bar_svg(data, categories, groups, title, width=700, colors=None):
    """100% stacked horizontal bars."""
    if colors is None:
        colors = ['#457B9D', '#E63946', '#2A9D8F', '#F7C948']

    n = len(groups)
    bar_h = 28
    margin_left = 110
    margin_right = 30
    margin_top = 55
    margin_bottom = 20
    chart_w = width - margin_left - margin_right
    total_h = n * (bar_h + 10) + margin_top + margin_bottom

    svg = f'<svg width="{width}" height="{total_h}" xmlns="http://www.w3.org/2000/svg" style="font-family:Inter,system-ui,sans-serif">\n'
    svg += f'<text x="{width/2}" y="22" text-anchor="middle" font-size="14" font-weight="600" fill="#1a1a2e">{title}</text>\n'

    lx = margin_left
    for i, c in enumerate(categories):
        svg += f'<rect x="{lx}" y="32" width="12" height="12" rx="2" fill="{colors[i]}"/>\n'
        svg += f'<text x="{lx+16}" y="43" font-size="10" fill="#555">{c}</text>\n'
        lx += len(c) * 6.5 + 28

    for gi, g in enumerate(groups):
        y = margin_top + gi * (bar_h + 10)
        svg += f'<text x="{margin_left - 10}" y="{y + bar_h/2 + 4}" text-anchor="end" font-size="12" fill="#333">{g}</text>\n'

        total = sum(data[g].get(c, 0) for c in categories)
        if total == 0:
            continue
        x = margin_left
        for ci, c in enumerate(categories):
            val = data[g].get(c, 0)
            pct = val / total
            bw = pct * chart_w
            if bw > 0:
                svg += f'<rect x="{x}" y="{y}" width="{bw}" height="{bar_h}" fill="{colors[ci]}" opacity="0.85"/>\n'
                if pct > 0.06:
                    svg += f'<text x="{x + bw/2}" y="{y + bar_h/2 + 4}" text-anchor="middle" font-size="10" fill="white" font-weight="500">{pct*100:.0f}%</text>\n'
                x += bw

    svg += '</svg>'
    return svg


# === BUILD THE HTML ===

# KPI cards
total = R['total_listings']
most_listings_city = cities_by_size[0]
most_listings_count = overview[most_listings_city]['total_listings']

# Highest median price (excluding Bangkok due to currency + Paris/Sydney no data)
price_ranking = sorted([(c, overview[c]['price_median']) for c in cities_with_prices if c != 'Bangkok'], key=lambda x: x[1] if x[1] else 0, reverse=True)

highest_price_city = price_ranking[0][0] if price_ranking else 'N/A'
highest_price_val = price_ranking[0][1] if price_ranking else 0

# Highest professional host share
pro_ranking = sorted(host_data.items(), key=lambda x: x[1]['professional_share'], reverse=True)

# Highest demand (avg RPM)
demand_ranking = sorted(demand_data.items(), key=lambda x: x[1]['avg_reviews_per_month'] if x[1]['avg_reviews_per_month'] else 0, reverse=True)

# --- Prepare chart data ---

# 1. Listings count bar chart
listings_data = {c: overview[c]['total_listings'] for c in cities_by_size}
listings_svg = make_bar_svg(listings_data, 'Total Listings by City', prefix='', color='#457B9D')

# 2. Median price bar chart (excl Bangkok, Paris, Sydney)
median_price_cities = sorted(
    [(c, overview[c]['price_median']) for c in cities_with_prices if c != 'Bangkok'],
    key=lambda x: x[1], reverse=True
)
median_price_data = dict(median_price_cities)
median_price_svg = make_bar_svg(median_price_data, 'Median Nightly Price by City (USD)', prefix='$', color='#E63946',
    note='Paris and Sydney excluded (100% missing prices). Bangkok excluded (prices appear to be in Thai Baht, not USD).')

# 3. Room type pricing grouped chart
rt_median_data = {}
for c in cities_with_prices:
    if c == 'Bangkok':
        continue
    rt_median_data[c] = {}
    for rt in ['Entire home/apt', 'Private room', 'Shared room']:
        if rt in price_data[c]:
            rt_median_data[c][rt] = price_data[c][rt]['median']

rt_price_groups = sorted(rt_median_data.keys(), key=lambda c: rt_median_data[c].get('Entire home/apt', 0), reverse=True)
rt_price_svg = make_grouped_bar_svg(rt_median_data, ['Entire home/apt', 'Private room', 'Shared room'],
    rt_price_groups, 'Median Nightly Price by City & Room Type (USD)')

# 4. Room type distribution stacked chart
rt_dist_data = {}
for c in cities_by_size:
    rt_dist_data[c] = overview[c]['room_type_counts']
rt_dist_svg = make_stacked_bar_svg(rt_dist_data, ['Entire home/apt', 'Private room', 'Shared room', 'Hotel room'],
    cities_by_size, 'Room Type Distribution by City (% of Listings)')

# 5. Professional host share
pro_sorted = sorted(host_data.items(), key=lambda x: x[1]['professional_share'], reverse=True)
pro_data = {c: v['professional_share'] for c, v in pro_sorted}
pro_svg = make_bar_svg(pro_data, 'Professional Host Share by City (hosts with 5+ listings)', prefix='', suffix='%', color='#2A9D8F')

# 6. Entire home share
eh_sorted = sorted(entire_home_data.items(), key=lambda x: x[1], reverse=True)
eh_data = dict(eh_sorted)
eh_svg = make_bar_svg(eh_data, 'Entire Home/Apt Share by City', prefix='', suffix='%', color='#E76F51')

# 7. Average reviews per month
rpm_sorted = sorted(demand_data.items(), key=lambda x: x[1]['avg_reviews_per_month'] if x[1]['avg_reviews_per_month'] else 0, reverse=True)
rpm_data = {c: v['avg_reviews_per_month'] for c, v in rpm_sorted}
rpm_svg = make_bar_svg(rpm_data, 'Average Reviews per Month by City', prefix='', color='#FF6B35')

# 8. Mean availability
avail_sorted = sorted(avail_data.items(), key=lambda x: x[1]['mean_availability'], reverse=True)
avail_bar_data = {c: v['mean_availability'] for c, v in avail_sorted}
avail_svg = make_bar_svg(avail_bar_data, 'Mean Annual Availability (days/365)', prefix='', suffix=' days', color='#264653')

# 9. Min nights 30+ pct
mn30_sorted = sorted(avail_data.items(), key=lambda x: x[1]['pct_30plus_min_nights'], reverse=True)
mn30_data = {c: v['pct_30plus_min_nights'] for c, v in mn30_sorted}
mn30_svg = make_bar_svg(mn30_data, 'Listings with 30+ Minimum Nights (%)', prefix='', suffix='%', color='#E63946',
    note='High percentages may indicate regulatory pressure favoring long-term rentals.')

# === HTML GENERATION ===

html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Global Airbnb Market Comparison</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap');

  * {{ margin: 0; padding: 0; box-sizing: border-box; }}

  body {{
    font-family: 'Inter', system-ui, -apple-system, sans-serif;
    background: #f8f9fa;
    color: #1a1a2e;
    line-height: 1.6;
  }}

  .hero {{
    background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
    color: white;
    padding: 60px 40px;
    text-align: center;
  }}

  .hero h1 {{
    font-size: 2.2rem;
    font-weight: 700;
    margin-bottom: 12px;
    letter-spacing: -0.5px;
  }}

  .hero .subtitle {{
    font-size: 1.05rem;
    color: #a8dadc;
    max-width: 800px;
    margin: 0 auto 20px;
    font-weight: 300;
  }}

  .hero .meta {{
    font-size: 0.85rem;
    color: #7f8c8d;
  }}

  .container {{
    max-width: 1100px;
    margin: 0 auto;
    padding: 0 24px;
  }}

  .kpi-row {{
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 16px;
    margin: -40px auto 40px;
    position: relative;
    z-index: 10;
  }}

  .kpi-card {{
    background: white;
    border-radius: 12px;
    padding: 24px;
    box-shadow: 0 4px 20px rgba(0,0,0,0.08);
    text-align: center;
  }}

  .kpi-card .kpi-value {{
    font-size: 1.8rem;
    font-weight: 700;
    color: #1a1a2e;
    margin-bottom: 4px;
  }}

  .kpi-card .kpi-label {{
    font-size: 0.8rem;
    color: #666;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    font-weight: 500;
  }}

  .kpi-card .kpi-detail {{
    font-size: 0.78rem;
    color: #888;
    margin-top: 4px;
  }}

  section {{
    background: white;
    border-radius: 12px;
    padding: 40px;
    margin-bottom: 24px;
    box-shadow: 0 2px 12px rgba(0,0,0,0.04);
  }}

  section h2 {{
    font-size: 1.5rem;
    font-weight: 700;
    color: #1a1a2e;
    margin-bottom: 8px;
    border-left: 4px solid #457B9D;
    padding-left: 16px;
  }}

  section .section-intro {{
    font-size: 0.95rem;
    color: #555;
    margin-bottom: 28px;
    padding-left: 20px;
  }}

  .chart-container {{
    display: flex;
    justify-content: center;
    margin: 24px 0;
    overflow-x: auto;
  }}

  table {{
    width: 100%;
    border-collapse: collapse;
    margin: 20px 0;
    font-size: 0.88rem;
  }}

  table th {{
    background: #f1f3f5;
    padding: 10px 14px;
    text-align: right;
    font-weight: 600;
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 0.3px;
    color: #555;
    border-bottom: 2px solid #dee2e6;
  }}

  table th:first-child {{
    text-align: left;
  }}

  table td {{
    padding: 10px 14px;
    text-align: right;
    border-bottom: 1px solid #eee;
    color: #333;
  }}

  table td:first-child {{
    text-align: left;
    font-weight: 500;
  }}

  table tr:hover {{
    background: #f8f9fa;
  }}

  .callout {{
    background: #edf6f9;
    border-left: 4px solid #457B9D;
    padding: 16px 20px;
    border-radius: 0 8px 8px 0;
    margin: 20px 0;
    font-size: 0.9rem;
    color: #333;
  }}

  .callout.warning {{
    background: #fff3e0;
    border-left-color: #F7C948;
  }}

  .callout strong {{
    color: #1a1a2e;
  }}

  .takeaway-list {{
    list-style: none;
    padding: 0;
  }}

  .takeaway-list li {{
    padding: 16px 20px;
    margin: 12px 0;
    background: #f8f9fa;
    border-radius: 8px;
    border-left: 4px solid #457B9D;
    font-size: 0.95rem;
    line-height: 1.7;
  }}

  .takeaway-list li strong {{
    color: #1a1a2e;
    display: block;
    margin-bottom: 4px;
  }}

  .two-col {{
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 24px;
  }}

