    margin_bottom = 30 if not note else 55
    chart_w = width - margin_left - margin_right
    chart_h = n * (bar_height + 8) + 10
    total_h = chart_h + margin_top + margin_bottom

    if max_val is None:
        max_val = max(v for _, v in items if v is not None and v > 0) * 1.15

    svg = f'<svg width="{width}" height="{total_h}" xmlns="http://www.w3.org/2000/svg" style="font-family:Inter,system-ui,sans-serif">\n'
    svg += f'<text x="{width/2}" y="22" text-anchor="middle" font-size="14" font-weight="600" fill="#1a1a2e">{title}</text>\n'

    for i, (label, val) in enumerate(items):
        y = margin_top + i * (bar_height + 8)
        svg += f'<text x="{margin_left - 10}" y="{y + bar_height/2 + 5}" text-anchor="end" font-size="12" fill="#333">{label}</text>\n'

        if val is not None and val > 0:
            bw = (val / max_val) * chart_w
            bw = max(bw, 2)
            svg += f'<rect x="{margin_left}" y="{y}" width="{bw}" height="{bar_height}" rx="4" fill="{color}" opacity="0.85"/>\n'
            label_text = f'{prefix}{val:,.0f}{suffix}' if isinstance(val, (int, float)) else str(val)
            svg += f'<text x="{margin_left + bw + 6}" y="{y + bar_height/2 + 5}" font-size="12" font-weight="500" fill="#333">{label_text}</text>\n'
        else:
            svg += f'<text x="{margin_left + 6}" y="{y + bar_height/2 + 5}" font-size="11" fill="#999">No data</text>\n'

    if note:
        svg += f'<text x="{width/2}" y="{total_h - 8}" text-anchor="middle" font-size="10" fill="#888" font-style="italic">{note}</text>\n'

    svg += '</svg>'
    return svg

def make_grouped_bar_svg(data, categories, groups, title, width=750, prefix='$'):
    """Grouped horizontal bar chart for room type pricing."""
    n_groups = len(groups)
    n_cats = len(categories)
    bar_h = 18
    group_gap = 15
    margin_left = 110
    margin_right = 100
    margin_top = 55
    margin_bottom = 40

    group_height = n_cats * (bar_h + 2) + group_gap
    chart_h = n_groups * group_height
    total_h = chart_h + margin_top + margin_bottom
    chart_w = width - margin_left - margin_right

    all_vals = []
    for g in groups:
        for c in categories:
            if g in data and c in data[g]:
                all_vals.append(data[g][c])
    max_val = max(all_vals) * 1.15 if all_vals else 100

    cat_colors = ['#457B9D', '#E63946', '#2A9D8F', '#F7C948']

    svg = f'<svg width="{width}" height="{total_h}" xmlns="http://www.w3.org/2000/svg" style="font-family:Inter,system-ui,sans-serif">\n'
    svg += f'<text x="{width/2}" y="22" text-anchor="middle" font-size="14" font-weight="600" fill="#1a1a2e">{title}</text>\n'

    # Legend
    lx = margin_left
    for i, c in enumerate(categories):
        svg += f'<rect x="{lx}" y="32" width="12" height="12" rx="2" fill="{cat_colors[i]}"/>\n'
        svg += f'<text x="{lx+16}" y="43" font-size="10" fill="#555">{c}</text>\n'
        lx += len(c) * 6 + 30

    for gi, g in enumerate(groups):
        gy = margin_top + gi * group_height
        svg += f'<text x="{margin_left - 10}" y="{gy + group_height/2 - 5}" text-anchor="end" font-size="12" fill="#333">{g}</text>\n'

        for ci, c in enumerate(categories):
            by = gy + ci * (bar_h + 2)
            val = data.get(g, {}).get(c, None)
            if val is not None and val > 0:
                bw = max((val / max_val) * chart_w, 2)
                svg += f'<rect x="{margin_left}" y="{by}" width="{bw}" height="{bar_h}" rx="3" fill="{cat_colors[ci]}" opacity="0.8"/>\n'
                svg += f'<text x="{margin_left + bw + 5}" y="{by + bar_h/2 + 4}" font-size="10" fill="#555">{prefix}{val:,.0f}</text>\n'

    svg += '</svg>'
    return svg

def make_stacked_bar_svg(data, categories, groups, title, width=700, colors=None):
    """100% stacked horizontal bars."""
    if colors is None:
        colors = ['#457B9D', '#E63946', '#2A9D8F', '#F7C948']

    n = len(groups)
    bar_h = 28
    margin_left = 110
    margin_right = 30
    margin_top = 55
    margin_bottom = 20
    chart_w = width - margin_left - margin_right
    total_h = n * (bar_h + 10) + margin_top + margin_bottom

    svg = f'<svg width="{width}" height="{total_h}" xmlns="http://www.w3.org/2000/svg" style="font-family:Inter,system-ui,sans-serif">\n'
    svg += f'<text x="{width/2}" y="22" text-anchor="middle" font-size="14" font-weight="600" fill="#1a1a2e">{title}</text>\n'

    lx = margin_left
    for i, c in enumerate(categories):
        svg += f'<rect x="{lx}" y="32" width="12" height="12" rx="2" fill="{colors[i]}"/>\n'
        svg += f'<text x="{lx+16}" y="43" font-size="10" fill="#555">{c}</text>\n'
        lx += len(c) * 6.5 + 28

    for gi, g in enumerate(groups):
        y = margin_top + gi * (bar_h + 10)
        svg += f'<text x="{margin_left - 10}" y="{y + bar_h/2 + 4}" text-anchor="end" font-size="12" fill="#333">{g}</text>\n'

        total = sum(data[g].get(c, 0) for c in categories)
        if total == 0:
            continue
        x = margin_left
        for ci, c in enumerate(categories):
            val = data[g].get(c, 0)
            pct = val / total
            bw = pct * chart_w
            if bw > 0:
                svg += f'<rect x="{x}" y="{y}" width="{bw}" height="{bar_h}" fill="{colors[ci]}" opacity="0.85"/>\n'
                if pct > 0.06:
                    svg += f'<text x="{x + bw/2}" y="{y + bar_h/2 + 4}" text-anchor="middle" font-size="10" fill="white" font-weight="500">{pct*100:.0f}%</text>\n'
                x += bw

    svg += '</svg>'
    return svg


